CREATE FUNCTION public.joined_group_campaign(cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.group_buying_participants WHERE campaign_id=cid AND user_id=auth.uid()) $$; REVOKE ALL ON FUNCTION public.joined_group_campaign(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.joined_group_campaign(uuid) TO authenticated; ALTER POLICY campaign_participant_read ON public.group_buying_campaigns USING(public.joined_group_campaign(id));